import { Component } from 'preact'
import i18n from '../../i18n'
import { getInitialState } from '../../helpers/state'

const CLASS = 'mv-response-form'

class ResponseForm extends Component {
  constructor(props) {
    super(props)

    // Get initial user data from localStorage or WordPress globals
    const initialData = getInitialState('response') || {}
    const currentUser = window.MV_CREATE?.currentUser || {}

    this.state = {
      authorName: currentUser.display_name || initialData.authorName || '',
      authorEmail: currentUser.user_email || initialData.authorEmail || '',
      content: '',
      errors: {}
    }

    this.handleSubmit = this.handleSubmit.bind(this)
    this.handleInputChange = this.handleInputChange.bind(this)
  }

  handleInputChange(field, value) {
    this.setState({ [field]: value, errors: {} })
  }

  validateForm() {
    const { authorName, content } = this.state
    const errors = {}

    if (!authorName.trim()) {
      errors.authorName = i18n('NAME_REQUIRED')
    }

    if (!content.trim()) {
      errors.content = i18n('RESPONSE_REQUIRED')
    }

    return errors
  }

  async handleSubmit(e) {
    e.preventDefault()

    const errors = this.validateForm()
    if (Object.keys(errors).length > 0) {
      this.setState({ errors })
      return
    }

    const { authorName, authorEmail, content } = this.state
    const responseData = {
      author_name: authorName.trim(),
      author_email: authorEmail.trim() || undefined,
      content: content.trim()
    }

    // Save to localStorage for future use
    localStorage.setItem('mv-create-response', JSON.stringify({
      authorName: authorName.trim(),
      authorEmail: authorEmail.trim()
    }))

    await this.props.onSubmit(responseData)
    
    // Clear content after successful submission
    this.setState({ content: '' })
  }

  render() {
    const { onCancel, submitting } = this.props
    const { authorName, authorEmail, content, errors } = this.state

    return (
      <form class={`${CLASS}`} onSubmit={this.handleSubmit}>
        <div class={`${CLASS}-fields`}>
          <div class={`${CLASS}-field`}>
            <label for="response-name" class={`${CLASS}-label`}>
              {i18n('NAME')} <span class={`${CLASS}-required`}>*</span>
            </label>
            <input
              id="response-name"
              type="text"
              class={`${CLASS}-input ${errors.authorName ? 'has-error' : ''}`}
              value={authorName}
              onInput={(e) => this.handleInputChange('authorName', e.target.value)}
              disabled={submitting}
              required
            />
            {errors.authorName && (
              <div class={`${CLASS}-error`}>{errors.authorName}</div>
            )}
          </div>

          <div class={`${CLASS}-field`}>
            <label for="response-email" class={`${CLASS}-label`}>
              {i18n('EMAIL')}
            </label>
            <input
              id="response-email"
              type="email"
              class={`${CLASS}-input ${errors.authorEmail ? 'has-error' : ''}`}
              value={authorEmail}
              onInput={(e) => this.handleInputChange('authorEmail', e.target.value)}
              disabled={submitting}
            />
            {errors.authorEmail && (
              <div class={`${CLASS}-error`}>{errors.authorEmail}</div>
            )}
          </div>

          <div class={`${CLASS}-field`}>
            <label for="response-content" class={`${CLASS}-label`}>
              {i18n('YOUR_RESPONSE')} <span class={`${CLASS}-required`}>*</span>
            </label>
            <textarea
              id="response-content"
              class={`${CLASS}-textarea ${errors.content ? 'has-error' : ''}`}
              value={content}
              onInput={(e) => this.handleInputChange('content', e.target.value)}
              disabled={submitting}
              rows="4"
              placeholder={i18n('WRITE_YOUR_RESPONSE')}
              required
            />
            {errors.content && (
              <div class={`${CLASS}-error`}>{errors.content}</div>
            )}
          </div>
        </div>

        <div class={`${CLASS}-actions`}>
          <button 
            type="button" 
            class={`${CLASS}-cancel`}
            onClick={onCancel}
            disabled={submitting}
          >
            {i18n('CANCEL')}
          </button>
          <button 
            type="submit" 
            class={`${CLASS}-submit`}
            disabled={submitting}
          >
            {submitting ? i18n('SUBMITTING') : i18n('SUBMIT_RESPONSE')}
          </button>
        </div>
      </form>
    )
  }
}

export default ResponseForm